// Keep only unseen RSS items and mark them seen immediately, so the same
// niche is never offered twice (even if a later pin fails). Items without an
// enclosure image are promo/test entries that will never get art — drop them.
const state = $getWorkflowStaticData('global');
state.seen = Array.isArray(state.seen) ? state.seen : [];

const seen = new Set(state.seen);
const fresh = [];

for (const item of $input.all()) {
  const j = item.json ?? {};
  const guid = String(j.guid ?? j.link ?? '');
  if (!guid || seen.has(guid)) continue;
  seen.add(guid);
  const imageUrl = String(j.enclosure?.url ?? '');
  if (!imageUrl) continue;
  fresh.push({ json: { ...j, guid, image_url: imageUrl } });
}

state.seen = Array.from(seen).slice(-2000);
return fresh.slice(0, 3); // steady drip: at most 3 pins per run

// Build the final Pinterest payload for one RSS item.
// Set BOARD_ID from the pinterest-list-boards workflow output.
const BOARD_ID = ''; // <-- your numeric Pinterest board id

const out = [];
for (const item of $input.all()) {
  const j = item.json ?? {};
  const src = String(j.contentSnippet ?? j.content ?? '');
  const description = [src.slice(0, 400), String(j.link ?? '')]
    .filter(Boolean).join('\n\n');
  out.push({
    json: {
      guid: String(j.guid ?? j.link ?? ''),
      boardId: BOARD_ID,
      image_url: String(j.image_url ?? ''),
      title: String(j.title ?? '').slice(0, 100),
      description: description.slice(0, 500),
      link: String(j.link ?? ''),
    },
  });
}
return out;
